import{_ as a,c as r,o,ag as e}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"播放器","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/player.md","filePath":"zh-TW/guide/player.md","lastUpdated":1791311600000}'),d={name:"zh-TW/guide/player.md"};function l(n,t,i,s,h,c){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="播放器" tabindex="-1">播放器 <a class="header-anchor" href="#播放器" aria-label="Permalink to &quot;播放器&quot;">​</a></h1><p>nPlyr 的播放器是一套由 <code>AVPlayer</code> 驅動、macOS 與 iOS 共用的核心。本頁介紹日常控制項與平台專屬手勢。</p><h2 id="開啟內容" tabindex="-1">開啟內容 <a class="header-anchor" href="#開啟內容" aria-label="Permalink to &quot;開啟內容&quot;">​</a></h2><p>從主畫面你可以：</p><ul><li><strong>開啟檔案</strong>——將本機影片拖入視窗，或使用檔案選擇器。</li><li><strong>開啟 URL</strong>——將直鏈（<code>.mp4</code>、<code>.m3u8</code>、<code>.flv</code>、<code>.ts</code> 等）貼到 URL 輸入框。</li><li><strong>從嗅探器開啟</strong>——將擷取的連結從<a href="/zh-TW/guide/browser.html">瀏覽器</a>抽屜直接傳送給播放器。</li><li><strong>從小程式開啟</strong>——點擊可播放的項目，nPlyr 會透過<a href="/zh-TW/guide/miniapps.html">規則引擎</a>解析它。</li></ul><h2 id="常用控制項-雙平台通用" tabindex="-1">常用控制項（雙平台通用） <a class="header-anchor" href="#常用控制項-雙平台通用" aria-label="Permalink to &quot;常用控制項（雙平台通用）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控制項</th><th>作用</th></tr></thead><tbody><tr><td>播放 / 暫停</td><td>空白鍵（macOS）或輕點影片中心（iOS）</td></tr><tr><td>進度</td><td>拖動進度條，或使用下方平台手勢</td></tr><tr><td>音量</td><td>系統 / 螢幕音量</td></tr><tr><td>倍速</td><td>透過倍速按鈕在 0.5×–3× 之間調整</td></tr><tr><td>音軌</td><td>當來源包含多音軌時可選擇</td></tr><tr><td>字幕</td><td>載入外部 <code>.srt</code> / <code>.vtt</code>，或使用內嵌音軌</td></tr><tr><td>畫中畫</td><td>將影片彈出為懸浮的畫中畫視窗</td></tr><tr><td>AirPlay</td><td>將影片傳送到 Apple TV 或 AirPlay 喇叭</td></tr><tr><td>DLNA（macOS）</td><td>投放到區域網路中的 DLNA 裝置</td></tr></tbody></table><h2 id="macos-手勢與快捷鍵" tabindex="-1">macOS 手勢與快捷鍵 <a class="header-anchor" href="#macos-手勢與快捷鍵" aria-label="Permalink to &quot;macOS 手勢與快捷鍵&quot;">​</a></h2><h3 id="觸控板" tabindex="-1">觸控板 <a class="header-anchor" href="#觸控板" aria-label="Permalink to &quot;觸控板&quot;">​</a></h3><ul><li><strong>橫向滑動</strong>拖動時間軸。拖動時<strong>預覽</strong>新位置；當你抬起手指（或停頓 250 毫秒）時才真正跳轉，因此誤滑絕不會讓影片亂跳。</li><li><strong>縱向滑動</strong>根據起始位置調整<strong>亮度</strong>或<strong>音量</strong>：影片<strong>左半側</strong>控制亮度，<strong>右半側</strong>控制音量。第一次滑動會鎖定軸向，二者互不干擾。</li><li><strong>滾輪</strong>懸停在進度條上時可微調位置（每格 ±5%）。</li></ul><h3 id="亮度" tabindex="-1">亮度 <a class="header-anchor" href="#亮度" aria-label="Permalink to &quot;亮度&quot;">​</a></h3><p>macOS 不提供公開 API 來調暗其他應用程式的影片，因此 nPlyr 在影片與控制項之間疊加一層調暗層。這只是視覺上的處理——底層畫面本身並未改變。</p><h3 id="鍵盤快捷鍵" tabindex="-1">鍵盤快捷鍵 <a class="header-anchor" href="#鍵盤快捷鍵" aria-label="Permalink to &quot;鍵盤快捷鍵&quot;">​</a></h3><p>快捷鍵僅按<strong>修飾鍵</strong>（<code>⌘</code>、<code>⌥</code>、<code>⌃</code>、<code>⇧</code>）匹配——方向鍵與小鍵盤不參與匹配，因此方向鍵綁定始終可靠。在文字框（URL 列、搜尋框等）中輸入時，單鍵快捷鍵會被抑制。</p><p>如果某個快捷鍵突然失效，請參閱<a href="/zh-TW/guide/troubleshooting.html">疑難排解</a>。</p><h2 id="ios-手勢" tabindex="-1">iOS 手勢 <a class="header-anchor" href="#ios-手勢" aria-label="Permalink to &quot;iOS 手勢&quot;">​</a></h2><ul><li><strong>雙擊</strong>將螢幕分為三個區域：輕點<strong>左三分之一</strong>後退 10 秒，<strong>右三分之一</strong>前進 10 秒，<strong>中間</strong>播放 / 暫停（並在點擊處顯示漣漪）。</li><li>**長按（0.5 秒）**暫時以 <strong>2.0×</strong> 播放；鬆開後恢復普通速度。</li><li>邊緣<strong>死區</strong>（約 30 pt，或短邊的 10%）被忽略，因此從螢幕邊緣開始滑動不會誤觸手勢。該死區僅在全螢幕時生效。</li></ul><h2 id="進階播放" tabindex="-1">進階播放 <a class="header-anchor" href="#進階播放" aria-label="Permalink to &quot;進階播放&quot;">​</a></h2><h3 id="多線路影片-json" tabindex="-1">多線路影片 JSON <a class="header-anchor" href="#多線路影片-json" aria-label="Permalink to &quot;多線路影片 JSON&quot;">​</a></h3><p>某些規則會回傳一個結構化 JSON，描述多條影片線路（不同解析度或 CDN）、字幕、歌詞與音訊 URL。nPlyr 將其解析為一個<strong>線路切換器</strong>，讓你在不丟失進度的情況下切換線路。</p><h3 id="續播與換源" tabindex="-1">續播與換源 <a class="header-anchor" href="#續播與換源" aria-label="Permalink to &quot;續播與換源&quot;">​</a></h3><ul><li>nPlyr 會記住你停在哪裡，並在下次提供<strong>續播</strong>選項。</li><li>在播放中途切換來源時，交換瞬間會<strong>凍結最後一幀</strong>，以免螢幕閃黑。</li><li>在項目就緒之前發出的跳轉會被<strong>排入佇列</strong>，並在播放可以開始的瞬間立即套用——因此你永遠不會在不知情的情況下從頭重播。</li></ul><h3 id="邊下邊播" tabindex="-1">邊下邊播 <a class="header-anchor" href="#邊下邊播" aria-label="Permalink to &quot;邊下邊播&quot;">​</a></h3><p>你可以在檔案仍在下載時就開始觀看。請參閱<a href="/zh-TW/guide/downloads.html">下載與媒體庫</a>。</p>',24)])])}const m=a(d,[["render",l]]);export{u as __pageData,m as default};
